#include <zmq.hpp>
#include <nlohmann/json.hpp>
#include <common/routing.hpp>
#include <iostream>
#include <chrono>
#include <thread>
using json = nlohmann::json;
namespace neuroswarm {
class ReflexLobe {
public:
    ReflexLobe(const std::string& ip = "localhost")
        : ctx(1), pub(ctx, zmq::socket_type::pub), sub(ctx, zmq::socket_type::sub) {
        pub.connect("tcp://" + ip + ":5555");
        sub.connect("tcp://" + ip + ":5556");
        routing::subscribe(sub, {"execution_result"});
        std::cout << "[REFLEX] Lobe online." << std::endl;
    }
    void start() {
        int total = 0, success = 0;
        while (true) {
            auto j = routing::receive(sub, zmq::recv_flags::dontwait);
            if (j.is_null()) { std::this_thread::sleep_for(std::chrono::milliseconds(100)); continue; }
            if (j.value("intent","") == "execution_result") {
                total++;
                if (j.value("status","") == "success") success++;
                if (total % 10 == 0) std::cout << "[REFLEX] Stats: " << success << "/" << total << " success rate" << std::endl;
            }
        }
    }
private:
    zmq::context_t ctx;
    zmq::socket_t pub, sub;
};
}
int main() { neuroswarm::ReflexLobe().start(); }
ENDOFFILE
